/** @anchor ui:journal:ExchangeCard
 * @tags ui */

import { createSignal, createEffect, createResource, onCleanup, For, Show } from 'solid-js'
import type {
  ExchangeAccount,
  TestConnectionResult,
  RiskSnapshot,
  VenueMargin,
  PositionEntry,
} from '../../api/client'
import { exchangeApi } from '../../api/client'
import { formatCurrency, formatNumber, formatPrice, pnlColor } from '../../lib/formatters'

interface KebabMenuProps {
  onTest: () => void
  onDelete: () => void
  onRevoke: () => void
  onImport: () => void
  showRevoke: boolean
  showImport: boolean
  isTesting: boolean
  isImporting: boolean
}

function KebabMenu(props: KebabMenuProps) {
  const [open, setOpen] = createSignal(false)
  const [confirmAction, setConfirmAction] = createSignal<'delete' | 'revoke' | null>(null)
  let ref: HTMLDivElement | undefined

  createEffect(() => {
    if (!open()) return
    const handler = (e: MouseEvent) => {
      if (ref && !ref.contains(e.target as Node)) {
        setOpen(false)
        setConfirmAction(null)
      }
    }
    document.addEventListener('mousedown', handler)
    onCleanup(() => document.removeEventListener('mousedown', handler))
  })

  return (
    <div ref={ref} class="relative">
      <button
        aria-label="Account options"
        aria-expanded={open()}
        onClick={() => {
          if (open()) setConfirmAction(null)
          setOpen(!open())
        }}
        class="btn-ghost text-text-tertiary hover:text-text-primary px-2 py-1 text-lg leading-none"
      >
        &#x22EE;
      </button>
      <Show when={open()}>
        <div class="absolute right-0 mt-1 w-44 bg-container-bg border border-container-border z-10 flex flex-col">
          <button
            onClick={() => {
              props.onTest()
              setOpen(false)
            }}
            class="btn-ghost text-left px-4 py-2.5 text-text-secondary hover:bg-main-bg transition-colors"
          >
            {props.isTesting ? 'TESTING...' : 'TEST CONNECTION'}
          </button>
          <Show when={props.showImport}>
            <button
              onClick={() => {
                props.onImport()
                setOpen(false)
              }}
              disabled={props.isImporting}
              class="btn-ghost text-left px-4 py-2.5 border-t border-container-border transition-colors disabled:opacity-50 text-text-secondary hover:bg-main-bg"
            >
              {props.isImporting ? 'IMPORTING...' : 'IMPORT'}
            </button>
          </Show>
          <Show when={props.showRevoke}>
            <Show
              when={confirmAction() === 'revoke'}
              fallback={
                <button
                  onClick={() => setConfirmAction('revoke')}
                  class="text-left px-4 py-2.5 text-xs font-mono text-signal-red hover:bg-signal-red/10 border-t border-container-border transition-colors"
                >
                  REVOKE AGENT
                </button>
              }
            >
              <div class="flex border-t border-container-border">
                <button
                  onClick={() => {
                    props.onRevoke()
                    setOpen(false)
                    setConfirmAction(null)
                  }}
                  class="btn-destructive flex-1 px-4 py-2.5 border-0"
                >
                  CONFIRM
                </button>
                <button
                  onClick={() => setConfirmAction(null)}
                  class="btn-ghost px-4 py-2.5 text-text-tertiary hover:bg-main-bg border-l border-container-border transition-colors"
                >
                  NO
                </button>
              </div>
            </Show>
          </Show>
          <Show
            when={confirmAction() === 'delete'}
            fallback={
              <button
                onClick={() => setConfirmAction('delete')}
                class="text-left px-4 py-2.5 text-xs font-mono text-signal-red hover:bg-signal-red/10 border-t border-container-border transition-colors"
              >
                DELETE
              </button>
            }
          >
            <div class="flex border-t border-container-border">
              <button
                onClick={() => {
                  props.onDelete()
                  setOpen(false)
                  setConfirmAction(null)
                }}
                class="btn-destructive flex-1 px-4 py-2.5 border-0"
              >
                CONFIRM
              </button>
              <button
                onClick={() => setConfirmAction(null)}
                class="btn-ghost px-4 py-2.5 text-text-tertiary hover:bg-main-bg border-l border-container-border transition-colors"
              >
                NO
              </button>
            </div>
          </Show>
        </div>
      </Show>
    </div>
  )
}

function formatBalanceUsd(raw: string): string {
  const num = parseFloat(raw)
  if (isNaN(num)) return '$0.00'
  return `$${Math.abs(num).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

function freeRatio(margin: VenueMargin): number {
  const total = parseFloat(margin.total_usd)
  const free = parseFloat(margin.free_usd)
  if (!isFinite(total) || total <= 0) return 0
  const pct = (free / total) * 100
  if (!isFinite(pct)) return 0
  return Math.max(0, Math.min(100, pct))
}

function PositionsSection(props: { positions: PositionEntry[] }) {
  const count = () => props.positions.length
  return (
    <div class="flex flex-col gap-2 pt-3 border-t border-container-border/50">
      <Show
        when={count() > 0}
        fallback={
          <div class="font-mono text-[10px] tracking-widest text-text-tertiary uppercase">
            ── NO OPEN POSITIONS ──
          </div>
        }
      >
        <div class="font-mono text-[10px] tracking-widest text-text-tertiary uppercase">
          ── {count()} {count() === 1 ? 'POSITION' : 'POSITIONS'} ──
        </div>
        <div class="flex flex-col gap-2">
          <For each={props.positions}>{(pos) => <PositionRow pos={pos} />}</For>
        </div>
      </Show>
    </div>
  )
}

function PositionRow(props: { pos: PositionEntry }) {
  const sideClass = () =>
    props.pos.side === 'long' ? 'text-signal-green' : 'text-signal-red'
  return (
    <div class="flex flex-col gap-0.5">
      <div class="flex items-center gap-2">
        <span class="font-mono text-xs text-text-primary">{props.pos.symbol}</span>
        <span class="font-mono text-[10px] text-text-tertiary">·</span>
        <span class={`font-mono text-[10px] uppercase tracking-wider ${sideClass()}`}>
          {props.pos.side}
        </span>
      </div>
      <div class="font-mono text-[10px] text-text-tertiary">
        {formatNumber(props.pos.quantity, 4)} @ {formatPrice(props.pos.entry_price)} &rarr;{' '}
        {formatPrice(props.pos.mark_price)}
      </div>
      <div class={`font-mono text-[10px] ${pnlColor(props.pos.unrealized_pnl_usd)}`}>
        {formatCurrency(props.pos.unrealized_pnl_usd)}
      </div>
    </div>
  )
}

interface ExchangeCardProps {
  account: ExchangeAccount
  testResult?: TestConnectionResult
  snapshot?: RiskSnapshot
  isTesting: boolean
  isDeleting: boolean
  isRevoking: boolean
  onTest: () => void
  onDelete: () => void
  onRevoke: () => void
  onMigrate: () => void
  onReauthorize: () => void
  onImport: () => void
  isImporting: boolean
}

export function ExchangeCard(props: ExchangeCardProps) {
  const isAgentWallet = () => props.account.auth_mode === 'agent_wallet'
  const walletAddr = () => props.account.agent_wallet_address
  const needsReauth = () => props.account.requires_reauthorization === true
  const venueMargin = (): VenueMargin | undefined =>
    props.snapshot?.margin_by_venue.find((m) => m.exchange_id === props.account.id)
  const venuePositions = (): PositionEntry[] =>
    props.snapshot?.positions_by_venue.find((v) => v.exchange_id === props.account.id)
      ?.positions ?? []

  // Transfer state (Hyperliquid only)
  const isHl = () => props.account.exchange_name === 'hyperliquid' && isAgentWallet();
  const [liveBal] = createResource(
    () => isHl() ? props.account.id : null,
    (id) => exchangeApi.fetchBalance(id),
  );
  const spotEntry = () => liveBal()?.balances.find(b => b.asset === 'USDC (Spot)');
  const perpEntry = () => liveBal()?.balances.find(b => b.asset === 'USDC (Perp)');
  const [trAmount, setTrAmount] = createSignal('');
  const [trPending, setTrPending] = createSignal(false);
  const [trMsg, setTrMsg] = createSignal('');
  const [toPerp, setToPerp] = createSignal(true); // spot→perp by default

  const sourceEntry = () => toPerp() ? spotEntry() : perpEntry();
  const destEntry = () => toPerp() ? perpEntry() : spotEntry();

  async function doTransfer() {
    const amt = trAmount().trim();
    if (!amt || isNaN(Number(amt)) || Number(amt) <= 0) { setTrMsg('Invalid amount'); return; }
    const max = parseFloat(sourceEntry()?.total ?? '0');
    if (Number(amt) > max) { setTrMsg('Insufficient balance'); return; }
    setTrPending(true); setTrMsg('');
    try {
      await exchangeApi.transferFunds(props.account.id, amt, toPerp());
      setTrAmount('');
      setTrMsg(`Sent ${amt} → ${toPerp() ? 'Perp' : 'Spot'}`);
    } catch (e: any) {
      setTrMsg(e?.message ?? 'Failed');
    }
    setTrPending(false);
  }

  return (
    <div class={`border ${
      needsReauth()
        ? 'border-signal-amber bg-signal-amber/5'
        : 'border-container-border bg-container-bg'
    } p-10 flex flex-col gap-6 min-h-[280px]`}>
      {/* Header: heartbeat + name + badge + kebab */}
      <div class="flex justify-between items-start">
        <div class="flex items-center gap-3">
          <span
            class={`inline-block w-2.5 h-2.5 rounded-full ${
              needsReauth()
                ? 'bg-signal-amber animate-pulse'
                : props.account.is_active
                  ? 'bg-signal-green animate-pulse'
                  : 'bg-signal-red'
            }`}
          />
          <h3 class="font-mono text-sm font-bold text-text-primary tracking-wider uppercase">
            {props.account.exchange_name}
          </h3>
          <span class="text-[10px] text-text-tertiary font-mono bg-main-bg px-2 py-0.5 border border-container-border">
            {isAgentWallet() ? 'DEX' : 'CEX'}
          </span>
          <Show when={needsReauth()}>
            <span class="text-[10px] text-signal-amber font-mono bg-signal-amber/10 px-2 py-0.5 border border-signal-amber/30">
              REAUTH REQUIRED
            </span>
          </Show>
        </div>
        <KebabMenu
          onTest={props.onTest}
          onDelete={props.onDelete}
          onRevoke={props.onRevoke}
          onImport={props.onImport}
          showRevoke={isAgentWallet()}
          showImport={true}
          isTesting={props.isTesting}
          isImporting={props.isImporting}
        />
      </div>

      {/* Identifier */}
      <span class="text-xs text-text-tertiary font-mono truncate">
        {walletAddr()
          ? `${walletAddr()!.slice(0, 6)}...${walletAddr()!.slice(-4)}`
          : props.account.account_name}
      </span>

      {/* Migration prompt for direct-key Hyperliquid */}
      <Show when={props.account.exchange_name === 'hyperliquid' && !isAgentWallet() && !needsReauth()}>
        <button
          onClick={props.onMigrate}
          class="text-[10px] font-mono text-signal-amber hover:underline text-left"
        >
          Migrate to agent wallet &rarr;
        </button>
      </Show>

      {/* Margin breakdown / test result — or reauth button when degraded */}
      <div class="mt-auto flex flex-col gap-2">
        <Show when={needsReauth()} fallback={
          <>
            <Show
              when={venueMargin()}
              fallback={
                <div class="font-mono text-xs text-text-tertiary">Margin unavailable</div>
              }
            >
              {(m) => (
                <div class="flex flex-col gap-1.5">
                  <div class="flex items-baseline gap-2">
                    <span class="font-mono text-2xl font-bold text-text-primary">
                      {formatBalanceUsd(m().total_usd)}
                    </span>
                    <span class="font-mono text-[10px] uppercase tracking-wider text-text-tertiary">
                      total
                    </span>
                  </div>
                  <div class="h-1.5 bg-text-primary/5 w-full">
                    <div
                      class="h-full bg-signal-green"
                      style={{ width: `${freeRatio(m())}%` }}
                    />
                  </div>
                  <div class="font-mono text-[10px] text-text-tertiary tracking-wider uppercase">
                    {formatBalanceUsd(m().free_usd)} free · {formatBalanceUsd(m().used_usd)} used
                  </div>

                  {/* Spot/Perp transfer — Hyperliquid agent wallets */}
                  <Show when={isHl() && !liveBal.loading}>
                    <div class="mt-2 pt-2 border-t border-container-border/30">
                      {/* Direction toggle + balances */}
                      <div class="flex items-center gap-1.5 mb-1.5">
                        <button onClick={() => setToPerp(true)}
                          class={`flex-1 text-center py-1 text-[10px] font-mono border transition-colors ${
                            toPerp() ? 'border-text-primary/40 bg-text-primary/5' : 'border-container-border'
                          }`}
                        >
                          <span class="block text-text-dim text-[8px] tracking-wider">SPOT</span>
                          <span class="font-bold text-signal-green">
                            {spotEntry() ? formatBalanceUsd(spotEntry()!.total) : '$0.00'}
                          </span>
                        </button>
                        <span class="text-text-dim text-sm">
                          {toPerp() ? <>&rarr;</> : <>&larr;</>}
                        </span>
                        <button onClick={() => setToPerp(false)}
                          class={`flex-1 text-center py-1 text-[10px] font-mono border transition-colors ${
                            !toPerp() ? 'border-text-primary/40 bg-text-primary/5' : 'border-container-border'
                          }`}
                        >
                          <span class="block text-text-dim text-[8px] tracking-wider">PERP</span>
                          <span class="font-bold text-signal-green">
                            {perpEntry() ? formatBalanceUsd(perpEntry()!.total) : '$0.00'}
                          </span>
                        </button>
                      </div>
                      {/* Amount input + action */}
                      <div class="flex gap-1">
                        <div class="flex-1 relative">
                          <input
                            type="number" step="0.01" min="0" placeholder="USDC"
                            value={trAmount()}
                            onInput={(e) => setTrAmount(e.currentTarget.value)}
                            class="w-full px-2 py-1.5 text-[11px] font-mono bg-main-bg border border-container-border text-text-primary"
                          />
                          <button
                            onClick={() => {
                              const src = sourceEntry();
                              if (src) setTrAmount(src.total)
                            }}
                            class="absolute right-1 top-1/2 -translate-y-1/2 px-1.5 py-0.5 text-[9px] font-mono font-bold text-text-dim hover:text-text-primary border border-container-border"
                          >
                            MAX
                          </button>
                        </div>
                        <button
                          onClick={doTransfer}
                          disabled={trPending()}
                          class="px-3 py-1.5 text-[10px] font-mono font-bold border border-text-primary text-text-primary hover:bg-text-primary hover:text-main-bg transition-colors disabled:opacity-50 whitespace-nowrap"
                        >
                          {toPerp() ? '→ Perp' : '→ Spot'}
                        </button>
                      </div>
                      <Show when={trMsg()}>
                        <p class={`text-[9px] font-mono mt-1 ${trMsg().startsWith('Sent') ? 'text-signal-green' : 'text-signal-red'}`}>{trMsg()}</p>
                      </Show>
                    </div>
                  </Show>
                </div>
              )}
            </Show>
            <PositionsSection positions={venuePositions()} />
            <Show when={props.testResult}>
              {(result) => (
                <div class="font-mono text-xs">
                  <Show
                    when={result().success}
                    fallback={<span class="text-signal-red">{result().error}</span>}
                  >
                    <span class="text-signal-green">{result().latency_ms}ms</span>
                  </Show>
                </div>
              )}
            </Show>
          </>
        }>
          <button
            onClick={() => props.onReauthorize()}
            class="w-full py-3 border border-signal-amber text-signal-amber font-mono font-bold text-xs tracking-wider hover:bg-signal-amber hover:text-main-bg transition-colors"
          >
            [ REAUTHORIZE ]
          </button>
        </Show>
      </div>
    </div>
  )
}

/** @anchor api:journal:exchange
 * @tags api */

import { fetchExchange } from './core'

export interface ExchangeInfo {
    id: string; name: string; display_name?: string; type: string
    exchange_type?: string; requires_passphrase?: boolean
    supported_features?: string[]; description?: string
    required_credentials?: string[]
}

export interface ExchangeAccount {
    id: string; exchange_name: string; account_name: string; is_active: boolean
    auth_mode: string; agent_wallet_address?: string | null
    requires_reauthorization?: boolean | null; last_used_at?: string | null
    created_at: string
}

export interface AddExchangeAccountPayload {
    exchange_name: string; account_name: string; api_key: string
    secret: string; passphrase?: string
}

export interface TestConnectionResult { success: boolean; latency_ms: number | null; error?: string }
export interface ExchangeBalanceEntry { asset: string; total: string; available: string; used: string }
export interface ExchangeBalanceResponse { balances: ExchangeBalanceEntry[] }
export interface InitAgentWalletResponse { account_id: string; agent_address: string }
export interface ApproveDataResponse { agent_address: string; typed_data: Record<string, unknown>; nonce: number }
export interface ApproveAgentResponse { success: boolean }
export interface MigrateToAgentWalletResponse { success: boolean }
export interface RevokeAgentResponse { success: boolean }

export const exchangeApi = {
    listExchanges: async () => {
        const res = await fetchExchange<{ exchanges: ExchangeInfo[] }>('')
        return res.exchanges
    },
    listAccounts: () => fetchExchange<ExchangeAccount[]>('/accounts'),
    addAccount: (payload: AddExchangeAccountPayload) =>
        fetchExchange<ExchangeAccount>('/accounts', { method: 'POST', body: JSON.stringify(payload) }),
    deleteAccount: (id: string) =>
        fetchExchange<void>(`/accounts/${id}`, { method: 'DELETE' }),
    testConnection: (id: string) =>
        fetchExchange<TestConnectionResult>(`/accounts/${id}/test`, { method: 'POST' }),
    fetchBalance: (id: string) =>
        fetchExchange<ExchangeBalanceResponse>(`/accounts/${id}/balance`),
    initAgentWallet: (walletAddress: string) =>
        fetchExchange<InitAgentWalletResponse>('/agent-wallet/init', {
            method: 'POST', body: JSON.stringify({ wallet_address: walletAddress }),
        }),
    getApproveData: (accountId: string) =>
        fetchExchange<ApproveDataResponse>('/agent-wallet/approve-data', {
            method: 'POST', body: JSON.stringify({ account_id: accountId }),
        }),
    approveAgent: (accountId: string, signature: string, nonce: number) =>
        fetchExchange<ApproveAgentResponse>('/agent-wallet/approve', {
            method: 'POST', body: JSON.stringify({ account_id: accountId, signature, nonce }),
        }),
    migrateToAgentWallet: (accountId: string, walletAddress: string) =>
        fetchExchange<MigrateToAgentWalletResponse>('/agent-wallet/migrate', {
            method: 'POST', body: JSON.stringify({ account_id: accountId, wallet_address: walletAddress }),
        }),
    revokeAgent: (id: string) =>
        fetchExchange<RevokeAgentResponse>(`/agent-wallet/${id}/revoke`, { method: 'DELETE' }),
    transferFunds: (id: string, amount: string, toPerp: boolean) =>
        fetchExchange<{ success: boolean; message: string }>(`/accounts/${id}/transfer`, {
            method: 'POST', body: JSON.stringify({ amount, to_perp: toPerp }),
        }),
}

/** @anchor ui:ext-popup:MainView
 * @tags ui */

import { createSignal, onMount, onCleanup, Show } from "solid-js";
import browser from "webextension-polyfill";
import { useAuth } from "../context/AuthContext";
import HeaderBar from "./HeaderBar";
import ArcGauge from "./ArcGauge";
import TabBar, { type TabId } from "./TabBar";
import TradeManagement from "./TradeManagement";
import ActiveOrders from "./ActiveOrders";
import { DESK_URL, type ExchangeMode } from "../../utils";
import type { BalanceResponse, LiveBalanceResponse } from "../../types";

function formatBalance(value: number): string {
  return value.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

export default function MainView(props: { onLogout: () => void }) {
  const auth = useAuth();
  const [activeTab, setActiveTabRaw] = createSignal<TabId>("trade");

  function setActiveTab(tab: TabId) {
    setActiveTabRaw(tab);
    browser.storage.local.set({ popupActiveTab: tab });
  }
  const [balance, setBalance] = createSignal<BalanceResponse[] | null>(null);
  const [exchangeName, setExchangeName] = createSignal<string | undefined>();
  const [noExchange, setNoExchange] = createSignal(false);
  const [balanceLoading, setBalanceLoading] = createSignal(true);
  const [positionCount, setPositionCount] = createSignal(0);
  const [pendingCount, setPendingCount] = createSignal(0);
  const [exchangeMode, setExchangeMode] = createSignal<ExchangeMode>("cex");
  let balanceRefreshTimer: ReturnType<typeof setTimeout> | null = null;

  // Transfer state
  const [transferAmount, setTransferAmount] = createSignal("");
  const [transferring, setTransferring] = createSignal(false);
  const [transferMsg, setTransferMsg] = createSignal("");

  const isHyperliquid = () => (exchangeName() ?? "").toLowerCase() === "hyperliquid";
  const spotBalance = () => balance()?.find(b => b.asset === "USDC (Spot)");
  const perpBalance = () => balance()?.find(b => b.asset === "USDC (Perp)");

  async function fetchBalance() {
    try {
      const resp = (await browser.runtime.sendMessage({
        type: "GET_BALANCE",
      })) as {
        success?: boolean;
        data?: LiveBalanceResponse;
        error?: string;
      };
      if (resp?.success && resp.data) {
        setBalance(resp.data.balances);
        setExchangeName(resp.data.exchange_name);
        setNoExchange(false);
      } else if (resp?.error === "No active exchange selected") {
        setNoExchange(true);
      }
    } catch {
      /* non-blocking */
    }
    setBalanceLoading(false);
  }

  async function doTransfer(toPerp: boolean) {
    const amount = transferAmount().trim();
    if (!amount || isNaN(Number(amount)) || Number(amount) <= 0) {
      setTransferMsg("Enter a valid amount");
      return;
    }
    setTransferring(true);
    setTransferMsg("");
    try {
      const resp = await browser.runtime.sendMessage({
        type: "TRANSFER_FUNDS",
        amount,
        toPerp,
      }) as { success?: boolean; message?: string; error?: string };
      if (resp?.success) {
        setTransferMsg(resp.message ?? "Done");
        setTransferAmount("");
        fetchBalance(); // refresh
      } else {
        setTransferMsg(resp?.error ?? "Transfer failed");
      }
    } catch (e: any) {
      setTransferMsg(e?.message ?? "Transfer failed");
    }
    setTransferring(false);
  }

  const usdt = () => balance()?.find((b) => b.asset === "USDT" || b.asset === "USDC");
  const available = () => (usdt() ? parseFloat(usdt()!.available) : null);
  const locked = () => (usdt() ? parseFloat(usdt()!.locked) : null);
  const total = () => {
    const u = usdt();
    if (!u) return null;
    // Use the exchange's total (includes unrealized PnL) rather than available+locked
    const t = parseFloat(u.total);
    if (!isNaN(t)) return t;
    // Fallback: sum available + locked if total missing
    const a = available();
    const l = locked();
    if (a === null && l === null) return null;
    return (a || 0) + (l || 0);
  };
  const exposure = () => {
    const t = total();
    const l = locked();
    if (!t || t === 0) return 0;
    return ((l || 0) / t) * 100;
  };

  function handleMessage(message: unknown) {
    const msg = message as { type: string; data?: { status?: string; e?: string } };
    if (msg.type === "WS_ORDER_UPDATE") {
      const status = msg.data?.status || msg.data?.e;
      const shouldRefresh = !status
        || status === "stopped_out"
        || status === "took_profit"
        || status === "entry_filled"
        || status === "closed"
        || status === "cancelled"
        || status === "trade_closed"
        || status === "manual_closed"
        || status.startsWith("reconciled_");
      if (shouldRefresh) {
        if (balanceRefreshTimer) clearTimeout(balanceRefreshTimer);
        balanceRefreshTimer = setTimeout(() => {
          balanceRefreshTimer = null;
          fetchBalance();
        }, 250);
      }
    }
  }

  // Re-fetch balance when active exchange or mode changes
  function handleStorageChange(changes: Record<string, { oldValue?: unknown; newValue?: unknown }>) {
    if (changes.exchangeMode) {
      setExchangeMode((changes.exchangeMode.newValue as ExchangeMode) || "cex");
    }
    if (changes.activeCexAccountId || changes.activeDexAccountId || changes.exchangeMode) {
      setBalance(null);        // Clear stale balance before fetching
      setBalanceLoading(true);
      fetchBalance();
    }
  }

  onMount(async () => {
    const stored = await browser.storage.local.get(["popupActiveTab"]);
    if (stored.popupActiveTab) setActiveTabRaw(stored.popupActiveTab as TabId);
    const modeRes = await browser.runtime.sendMessage({ type: "GET_EXCHANGE_MODE" }) as { mode: ExchangeMode };
    if (modeRes?.mode) setExchangeMode(modeRes.mode);
    fetchBalance();
    browser.runtime.onMessage.addListener(handleMessage);
    browser.storage.onChanged.addListener(handleStorageChange);
  });

  onCleanup(() => {
    browser.runtime.onMessage.removeListener(handleMessage);
    browser.storage.onChanged.removeListener(handleStorageChange);
    if (balanceRefreshTimer) {
      clearTimeout(balanceRefreshTimer);
      balanceRefreshTimer = null;
    }
  });

  return (
    <div class="flex flex-col h-full">
      {/* Slim toolbar */}
      <header>
        <HeaderBar onLogout={props.onLogout} />
      </header>

      {/* Wallet-style balance panel */}
      <div class="balance-panel" data-testid="header-balance">
        <div class="balance-panel-overlay" aria-hidden="true" />
        <div class="flex flex-col items-center pt-5 pb-2">
          <div class="flex items-center gap-2 mb-2">
            <span class="text-[12px] font-medium text-text-primary/70 tracking-widest uppercase">
              Balance
            </span>
            <Show when={exchangeName()}>
              {/* UXP-17: white badge instead of accent-green */}
              <span class="text-[10px] font-bold text-text-primary bg-text-primary/10 px-1.5 py-0.5 tracking-wider uppercase">
                {exchangeName()}
              </span>
            </Show>
          </div>
          <span
            class="text-[42px] font-bold text-text-primary tracking-tight leading-none text-shadow-balance"
          >
            <Show
              when={!balanceLoading() && total() !== null}
              fallback={
                <Show
                  when={!balanceLoading() && noExchange()}
                  fallback={<span class="balance-loading text-text-primary/60">$--</span>}
                >
                  <div class="mx-4 my-3 p-4 border border-text-primary/10 text-center">
                    <p class="text-sm text-text-dim mb-2">
                      {exchangeMode() === "dex" ? "No wallet connected" : "No CEX exchange linked"}
                    </p>
                    {/* UX-07: primary CTA */}
                    <button
                      class="btn-primary"
                      onClick={() => window.open(`${DESK_URL}/account?source=extension`, "_blank")}
                      data-testid="connect-account-cta"
                    >
                      {exchangeMode() === "dex" ? "Connect Wallet" : "Connect Account"}
                    </button>
                  </div>
                </Show>
              }
            >
              ${formatBalance(total()!)}
            </Show>
          </span>
          {/* Loading hint */}
          <Show when={balanceLoading()}>
            <span class="text-[12px] text-text-dim font-sans mt-1">Fetching balance...</span>
          </Show>
          {/* Delta line: available / locked breakdown — KEEP: trading data */}
          <Show when={!balanceLoading() && available() !== null}>
            <div class="flex items-center gap-2 mt-2">
              <span class="text-[12px] text-signal-green font-medium">
                ${formatBalance(available()!)} available
              </span>
              <span class="text-text-dim">·</span>
              <span class="text-[12px] text-text-secondary">
                ${formatBalance(locked()!)} locked
              </span>
            </div>
          </Show>
        </div>

        {/* Risk gauge */}
        <ArcGauge
          exposure={exposure()}
          atRisk={locked() || 0}
          totalBalance={total() || 0}
        />
      </div>

      {/* Tabs */}
      <TabBar
        activeTab={activeTab()}
        onTabChange={setActiveTab}
        positionCount={positionCount()}
        pendingCount={pendingCount()}
      />

      {/* Content — "control deck" with denser background */}
      <main class="flex-1 min-h-0 scroll-area bg-bg-panel">
        <Show when={activeTab() === "trade"}>
          <div role="tabpanel" id="panel-trade" aria-labelledby="tab-trade">
            <TradeManagement />
          </div>
        </Show>

        <Show when={activeTab() === "positions"}>
          <div role="tabpanel" id="panel-positions" aria-labelledby="tab-positions">
          <ActiveOrders
            onCountChange={(active, pending) => {
              setPositionCount(active);
              setPendingCount(pending);
            }}
            onBalanceRefresh={fetchBalance}
            isDex={exchangeMode() === "dex"}
          />
          </div>
        </Show>

        <Show when={activeTab() === "account"}>
          <div role="tabpanel" id="panel-account" aria-labelledby="tab-account" class="px-5 py-4 space-y-4" data-testid="balance-section">
            {/* Info Grid */}
            <Show
              when={!balanceLoading()}
              fallback={
                <p class="text-[14px] text-text-dim font-sans">Loading...</p>
              }
            >
              <Show
                when={available() !== null}
                fallback={
                  <p class="text-[14px] text-text-dim italic font-sans">
                    {noExchange()
                      ? (exchangeMode() === "dex" ? "No wallet connected" : "No CEX exchange linked")
                      : "Balance unavailable"}
                  </p>
                }
              >
                <div class="info-grid">
                  <div class="info-grid-cell">
                    <span class="block text-[11px] text-text-secondary font-sans font-medium mb-1">
                      Available
                    </span>
                    <span
                      class="text-[15px] text-signal-green font-mono font-bold"
                      data-testid="balance-available"
                    >
                      {formatBalance(available()!)}
                    </span>
                  </div>
                  <div class="info-grid-cell">
                    <span class="block text-[11px] text-text-secondary font-sans font-medium mb-1">
                      Locked
                    </span>
                    <span
                      class="text-[15px] text-signal-orange font-mono font-bold"
                      data-testid="balance-locked"
