                      {formatBalance(locked()!)}
                    </span>
                  </div>
                  <div class="info-grid-cell">
                    <span class="block text-[11px] text-text-secondary font-sans font-medium mb-1">
                      Positions
                    </span>
                    <span class="text-[15px] text-text-primary font-mono font-bold">
                      {positionCount()}
                    </span>
